# coding: utf-8
from lesson_authoring import entry as E
S=[['拉丁 salvus → 晚期拉丁 salvare','安然无恙 → 使安全、保全'],['古法语 sauver → 英语 save','救回；保留下来']]
F=[['拉丁 salvus → 古法语 sauf','安然无恙、得到保护'],['中古英语 sauf → safe','安全的、没有受损的']]
W=[
E('save','/seɪv/','救；保存；节省；攒下','把本来可能失去的东西留住：人命、文件、钱、时间都可以是对象。','从古法语 sauver 借入，接晚期拉丁 salvare；不是把现代 safe 的 f 简单改成 v 才造出。',S,'save a life 是把生命救下来；save a file 是把工作成果留住；save money 可说省钱，也可说攒钱。共同画面是让重要的东西不丢掉、不耗掉。save someone the trouble 则是让某人免去麻烦。','save someone from danger；save a file；save up for a trip；save time。','rescue 更集中在脱离危险；save 的范围更大。save money on food 是减少食品开销，save money for a trip 是为旅行积攒。',('Please save your work before closing the program.','关闭程序前请保存你的工作。'),('We are saving up for a trip next year.','我们正在为明年的旅行攒钱。'),('Taking the train saved us two hours.','坐火车让我们省了两个小时。'),sources=['https://www.etymonline.com/word/save','https://en.wiktionary.org/wiki/save']),
E('safe','/seɪf/','安全的；稳妥的；保险箱','东西还完好，人没有受伤，危险暂时够不着他们。','形容词经古法语 sauf 借入，源自 salvus；名词保险箱与法语“安全存放”的表达及英语形容词相联系。',F+[['安全存放物品的容器 → 名词 safe','保险箱']],'The children are safe 是孩子们平安；a safe choice 是比较稳妥的选择；put it in the safe 里的 safe 则是保险箱。把人、选择、容器放回句子，词性和意思就清楚了。','keep someone safe；safe from harm；a safe place；lock something in a safe。','safe 是处于安全状态，save 是保全的动作。secure 常突出保护牢靠或不易被侵入，safe 的日常范围更广。',('The children were safe inside the house.','孩子们在屋里很安全。'),('She kept the documents in a small safe.','她把文件放在一个小保险箱里。'),sources=['https://www.etymonline.com/word/safe','https://en.wiktionary.org/wiki/safe']),
E('safety','/ˈseɪfti/','安全；平安；安全保障','把 safe 这种状态当作一件需要关心、维护的事。','历史上经古法语 sauveté、salvetet 借入，接中古拉丁 salvitas；现代可与 safe + 名词 -ty 联系。',[['拉丁 salvus → 中古拉丁 salvitas','安全的 → 安全状态'],['古法语 sauveté → 英语 safety','安全、免受伤害']],'for your safety 是为了你的安全；reach safety 是到达安全地带。英语可以把安全状态说成目的地，因此 bring someone to safety 不必逐字翻成“带某人到安全”。','for safety；safety equipment；reach safety；concern for someone’s safety。','safety 是名词，safe 是形容词。说明安全措施可用 safety measures，不能把词尾 -ty 当成“很多个安全”。',('The workers checked the safety equipment before starting.','工人们开工前检查了安全装备。'),('The hikers finally reached safety before dark.','徒步者终于在天黑前到达了安全地带。'),sources=['https://www.etymonline.com/word/safety','https://en.wiktionary.org/wiki/safety']),
E('safely','/ˈseɪfli/','安全地；平安地；稳妥地','关注一件事是怎么完成的，或最后有没有平安完成。','safe + -ly；对应中古英语 savely。',F+[['safe + -ly → safely','以安全方式；平安地']],'arrive safely 是平安抵达；store something safely 是妥善存放。We can safely assume 表示根据现有情况可以稳妥地推断，并非在谈身体危险。','arrive safely；land safely；store safely；safely assume。','She is safe 说她的状态；She arrived safely 说到达的结果。词尾 -ly 把描述接到动作或判断上。',('The plane landed safely despite the strong wind.','尽管风很大，飞机仍然安全着陆。'),('Keep the original files safely stored.','把原始文件妥善保存好。'),sources=['https://en.wiktionary.org/wiki/safely','https://www.etymonline.com/word/safely']),
E('unsafe','/ʌnˈseɪf/','不安全的；有风险的','某种条件让人或东西容易遭到伤害，不能放心使用或靠近。','un- 不 + safe 安全的。',F+[['un- + safe → unsafe','没有达到安全条件的']],'an unsafe bridge 是存在危险的桥；unsafe working conditions 是不安全的工作条件。unsafe 指有风险，并不要求事故已经发生。','unsafe conditions；unsafe equipment；unsafe to use；feel unsafe。','unsafe 是对安全状况的判断；uncomfortable 是不舒服，两者可能重叠但并不等同。',('The old bridge was declared unsafe.','这座旧桥被认定为不安全。'),('She felt unsafe walking through the empty parking lot.','她走过空荡荡的停车场时觉得不安全。'),sources=['https://en.wiktionary.org/wiki/unsafe','https://www.etymonline.com/word/unsafe']),
E('safeguard','英 /ˈseɪfɡɑːd/；美 /ˈseɪfɡɑrd/','保护；保障措施','提前设一道保护，让重要的东西不至于轻易受损。','来自古法语 sauve garde：安全的 + 看守、保护；现代可直接识别 safe + guard。',[['古法语 sauve 安全的 + garde 看守、保护','保障、保管'],['英语 safeguard 名词 → 动词','保护措施 → 加以保护']],'safeguard privacy 是保护隐私；a safeguard against mistakes 是防止差错的一项措施。它常强调具体机制、制度或防护安排，而不只是口头说“放心”。','safeguard rights；safeguard information；a safeguard against misuse。','guard 可以指守卫的人；safeguard 更常指保障行为或措施，不是所有带 guard 的词都在说一位保安。',('The policy aims to safeguard personal information.','这项政策旨在保护个人信息。'),('A second review provides a safeguard against simple errors.','再检查一遍能防止一些简单错误。'),sources=['https://www.etymonline.com/word/safeguard','https://en.wiktionary.org/wiki/safeguard'])]
